import{_ as t,c as a,o as i,aj as o}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse(`{"title":"Colorado Style Pizza Dough","description":"Cold-fermented pizza dough inspired by Fargo's Pizza Co., with malty flavor, soft interior, and crisp crust.","frontmatter":{"title":"Colorado Style Pizza Dough","description":"Cold-fermented pizza dough inspired by Fargo's Pizza Co., with malty flavor, soft interior, and crisp crust.","head":[["meta",{"name":"description","content":"Cold-fermented pizza dough inspired by Fargo's Pizza Co., with malty flavor, soft interior, and crisp crust."}],["meta",{"property":"og:title","content":"Colorado Style Pizza Dough"}],["meta",{"property":"og:description","content":"Cold-fermented pizza dough inspired by Fargo's Pizza Co., with malty flavor, soft interior, and crisp crust."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/colorado-pizza-dough.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Colorado Style Pizza Dough"}],["meta",{"name":"twitter:description","content":"Cold-fermented pizza dough inspired by Fargo's Pizza Co., with malty flavor, soft interior, and crisp crust."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/colorado-pizza-dough.html"}]]},"headers":[],"relativePath":"recipes/colorado-pizza-dough.md","filePath":"recipes/colorado-pizza-dough.md"}`),r={name:"recipes/colorado-pizza-dough.md"};function n(l,e,s,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="colorado-style-pizza-dough" tabindex="-1">Colorado Style Pizza Dough <a class="header-anchor" href="#colorado-style-pizza-dough" aria-label="Permalink to “Colorado Style Pizza Dough”">​</a></h1><p>A cold-fermented dough inspired by the original Fargo&#39;s Pizza Co. style. This version is tuned for home baking: malty flavor, tender interior, and crisp crust. Use the <a href="https://calculator.kitchenratio.com" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>When I worked at Fargo&#39;s Pizza Co., I didn&#39;t have the exact formula, but I worked with that dough every day for nearly 20 years. This recipe comes from that hands-on experience, plus a few adjustments that make it more practical at home.</p><p>The original dough ran at a much <strong>lower hydration</strong>, closer to a cracker-style texture, which worked well with a commercial dough sheeter. For home baking, increasing hydration improves:</p><ul><li>Extensibility</li><li>Handling (without a sheeter)</li><li>Crust texture: lighter, less dense, and more open</li></ul><p>If you want something closer to the restaurant version, reduce hydration.<br> If you drop it <strong>below 65%</strong>, I recommend kneading for <strong>8-10 minutes</strong> after mixing.</p><hr><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 550g</li><li><strong>Water</strong> - 363g (66% hydration)</li><li><strong>Yeast</strong> - 1.6g (0.3%)</li><li><strong>Olive oil</strong> - 39g (7%)</li><li><strong>Salt</strong> - 11g (2%)</li><li><strong>Light malt powder</strong> - 11g (2%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch makes <strong>about three 11-inch (&quot;Medium&quot;) pizzas</strong> depending on how thick you make the crust. I usually stretch mine to about 1/4-1/2 inch thick before adding toppings.</p><p>The low yeast percentage (0.3%) slows fermentation during the long cold rise:<br><strong>24 hours bulk fermentation</strong>, followed by <strong>24-48 hours cold proofing</strong>.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine all ingredients until a rough, cohesive dough forms.</li><li>If using active dry yeast, hydrate it in water for about 10 minutes before adding the rest of the ingredients.</li><li>Intensive kneading isn&#39;t necessary at this hydration level.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>You have two options for adding the oil:</p><ul><li><strong>Add it during mixing</strong> - easiest, but may slightly affect gluten development.</li><li><strong>Add it after the two folds</strong> - better gluten formation, but requires kneading the oil in.</li></ul><p>If adding it later:<br> The dough may temporarily look like it&#39;s coming apart when you begin kneading in the oil. This is normal. Stay patient and continue pressing the dough with your palms, folding, rotating, and pressing again. It will come back together faster than it seems.</p></div><h3 id="_2-bulk-fermentation-cold" tabindex="-1">2. Bulk Fermentation (Cold) <a class="header-anchor" href="#_2-bulk-fermentation-cold" aria-label="Permalink to “2. Bulk Fermentation (Cold)”">​</a></h3><ul><li>Place the dough in the refrigerator for <strong>24 hours</strong>.</li><li>Perform <strong>2 gentle folds</strong> within the first hour to strengthen the dough: <ul><li>Mix the dough and place it in the refrigerator.</li><li>After 30 minutes, remove, perform one fold, and return to the fridge.</li><li>After another 30 minutes, perform the second fold and refrigerate.</li></ul></li><li>If you delayed adding the oil, add it after the folds. Let the dough rest a few hours, then knead in the oil just before leaving it to rest overnight.</li></ul><h3 id="_3-final-proof" tabindex="-1">3. Final Proof <a class="header-anchor" href="#_3-final-proof" aria-label="Permalink to “3. Final Proof”">​</a></h3><ul><li>Divide and shape into dough balls, stretching each against the counter to tighten.</li><li>Place the balls into a tray, or separate containers with a bit of olive oil to prevent sticking.</li><li>Cold proof for <strong>24-48 hours</strong> for the best flavor and extensibility.</li></ul><h3 id="_4-shaping" tabindex="-1">4. Shaping <a class="header-anchor" href="#_4-shaping" aria-label="Permalink to “4. Shaping”">​</a></h3><ul><li>Allow the dough balls to warm before shaping. Remove from refrigeration for 1-2 hours.</li><li>Gently press and stretch into rounds while preserving gas in the dough.</li><li>Use your fingertips to press outward in a circular pattern, leaving a slight ridge around the edge.</li><li>Avoid over-degassing as it affects texture.</li><li>Top with sauce and ingredients, being careful not to overload the dough.</li></ul><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>Move the dough to a peel before topping, and use plenty of flour or cornmeal to prevent sticking.</p><p>Put it on the edge of the peel so it slides off easily onto the stone or steel in the oven.</p></div><h3 id="_5-baking" tabindex="-1">5. Baking <a class="header-anchor" href="#_5-baking" aria-label="Permalink to “5. Baking”">​</a></h3><ul><li>Preheat your oven as hot as it will go: <ul><li>Most home ovens reach <strong>450-500°F</strong></li><li>Some can reach <strong>500-550°F</strong></li></ul></li><li>Bake on a pizza stone or steel until the crust is golden and crisp.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/cold-fermentation.html">Cold Fermentation</a></li><li><a href="/ingredients/flour.html">Flour</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/cold-iron-cloud-pan-pizza.html">Cold Iron Cloud Pan Pizza</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong><br> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',34)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
